practice.question:
A music app lets a phone and tablet edit the same ordered playlist while offline. Use Yjs shared types and document updates so both replicas converge after reconnecting.

Prerequisites: Node.js 20+ with npm.

Setup:

```bash
mkdir yjs-playlist-lab
cd yjs-playlist-lab
npm init -y
npm pkg set type=module
npm install --save-exact yjs@13.6.31
npm ls yjs
```

:::cut Create the starter files
Save this as `playlist.mjs`:

```javascript
import * as Y from "yjs";

export function createBaseUpdate() {
  const seed = new Y.Doc();
  seed.getArray("playlist").insert(0, ["t1", "t2", "t3"]);
  return Y.encodeStateAsUpdate(seed);
}

export function createReplica(baseUpdate) {
  const doc = new Y.Doc();
  Y.applyUpdate(doc, baseUpdate);
  return doc;
}

export function editOffline(baseUpdate) {
  const phone = createReplica(baseUpdate);
  const tablet = createReplica(baseUpdate);
  const phoneState = Y.encodeStateVector(phone);
  const tabletState = Y.encodeStateVector(tablet);
  const phonePlaylist = phone.getArray("playlist");
  const tabletPlaylist = tablet.getArray("playlist");

  // TODO: apply offline edits

  return {
    phone,
    tablet,
    phoneUpdate: Y.encodeStateAsUpdate(phone, phoneState),
    tabletUpdate: Y.encodeStateAsUpdate(tablet, tabletState),
  };
}

export function syncReplicas(phone, tablet, phoneUpdate, tabletUpdate) {
  // TODO: exchange updates

  return {
    phone: phone.getArray("playlist").toArray(),
    tablet: tablet.getArray("playlist").toArray(),
  };
}
```

Save this as `playlist.test.mjs`:

```javascript
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import test from "node:test";
import * as Y from "yjs";
import {
  createBaseUpdate,
  createReplica,
  editOffline,
  syncReplicas,
} from "./playlist.mjs";

const tracks = (doc) => doc.getArray("playlist").toArray();

test("offline playlist edits converge", () => {
  const baseUpdate = createBaseUpdate();
  const { phone, tablet, phoneUpdate, tabletUpdate } = editOffline(baseUpdate);

  assert.deepEqual(tracks(phone), ["t1", "t3", "t4"]);
  assert.deepEqual(tracks(tablet), ["t3", "t1", "t2"]);

  const merged = syncReplicas(phone, tablet, phoneUpdate, tabletUpdate);
  assert.deepEqual(merged.phone, ["t3", "t1", "t4"]);
  assert.deepEqual(merged.tablet, merged.phone);

  Y.applyUpdate(phone, tabletUpdate);
  assert.deepEqual(tracks(phone), merged.phone);

  const phoneFirst = createReplica(baseUpdate);
  const tabletFirst = createReplica(baseUpdate);
  Y.applyUpdate(phoneFirst, phoneUpdate);
  Y.applyUpdate(phoneFirst, tabletUpdate);
  Y.applyUpdate(tabletFirst, tabletUpdate);
  Y.applyUpdate(tabletFirst, phoneUpdate);
  assert.deepEqual(tracks(phoneFirst), tracks(tabletFirst));
  assert.deepEqual(tracks(phoneFirst), merged.phone);
});

test("notes explain the CRDT choices", () => {
  assert.ok(existsSync("notes.md"), "notes.md must exist");
  const notes = readFileSync("notes.md", "utf8").trim();
  const sentences = notes.split(/(?<=[.!?])\s+/).filter(Boolean);

  assert.ok(sentences.length >= 2 && sentences.length <= 4);
  assert.match(notes, /\bY\.Array\b/i);
  assert.match(notes, /\b(?:order(?:ed|ing)?|sequence|position(?:s|al)?)\b/i);
  assert.match(notes, /\b(?:delet(?:e|es|ed|ing|ion)|remov(?:e|es|ed|ing|al))\b/i);
  assert.match(notes, /\binsert(?:s|ed|ing|ion)?\b/i);
  assert.match(notes, /\b(?:move|moves|moved|moving|reorder(?:s|ed|ing)?)\b/i);
  assert.match(notes, /\b(?:exchang(?:e|es|ed|ing)|appl(?:y|ies|ied|ying)|sync(?:s|ed|ing)?|synchroniz(?:e|es|ed|ing|ation)|shar(?:e|es|ed|ing)|send|sends|sending|sent|receiv(?:e|es|ed|ing)|deliver(?:s|ed|ing|y))\b/i);
  assert.match(notes, /\bupdates?\b/i);
  assert.match(notes, /\b(?:converg(?:e|es|ed|ing|ence)|consistent|same|identical|agree(?:s|d|ment)?)\b/i);
});
```
:::

Tasks:

1. Complete `editOffline` with native `Y.Array` operations. On the phone, delete `t2` and append `t4`. On the tablet, move `t3` to the head by deleting its current occurrence and inserting it at index `0`. Keep the supplied state-vector and incremental-update workflow; do not exchange plain arrays or build a custom CRDT.
2. Complete `syncReplicas` by applying each replica's incremental binary update to the other replica with `Y.applyUpdate`.
3. Run the tests:

   ```bash
   node --test playlist.test.mjs
   ```

4. Write `notes.md` with 2–4 sentences explaining why `Y.Array` is appropriate for an ordered playlist, why delete-and-insert represents a move, and why exchanging Yjs updates converges despite duplicate delivery or different delivery order.

practice.answer:
playlist.mjs:
```js
import * as Y from "yjs";

export function createBaseUpdate() {
  const seed = new Y.Doc();
  seed.getArray("playlist").insert(0, ["t1", "t2", "t3"]);
  return Y.encodeStateAsUpdate(seed);
}

export function createReplica(baseUpdate) {
  const doc = new Y.Doc();
  Y.applyUpdate(doc, baseUpdate);
  return doc;
}

export function editOffline(baseUpdate) {
  const phone = createReplica(baseUpdate);
  const tablet = createReplica(baseUpdate);
  const phoneState = Y.encodeStateVector(phone);
  const tabletState = Y.encodeStateVector(tablet);
  const phonePlaylist = phone.getArray("playlist");
  const tabletPlaylist = tablet.getArray("playlist");

  phonePlaylist.delete(1, 1);
  phonePlaylist.push(["t4"]);

  const t3Index = tabletPlaylist.toArray().indexOf("t3");
  tabletPlaylist.delete(t3Index, 1);
  tabletPlaylist.insert(0, ["t3"]);

  return {
    phone,
    tablet,
    phoneUpdate: Y.encodeStateAsUpdate(phone, phoneState),
    tabletUpdate: Y.encodeStateAsUpdate(tablet, tabletState),
  };
}

export function syncReplicas(phone, tablet, phoneUpdate, tabletUpdate) {
  Y.applyUpdate(phone, tabletUpdate);
  Y.applyUpdate(tablet, phoneUpdate);

  return {
    phone: phone.getArray("playlist").toArray(),
    tablet: tablet.getArray("playlist").toArray(),
  };
}
```

notes.md:
```md
Y.Array is appropriate because it keeps an ordered playlist sequence as a shared CRDT type. Moving `t3` is represented by deleting its old occurrence and inserting it at the head. Replicas exchange Yjs updates and converge to the same state even when updates are delivered more than once or in a different order.
```

