import assert from "node:assert/strict";
import test from "node:test";
import {
  ISBN,
  ISBN2,
  createInventory,
  forkReplica,
  mergeReplicas,
  restock,
  sell,
  value,
} from "./inventory.mjs";

test("concurrent sales converge without losing a decrement", () => {
  const base = createInventory({ [ISBN]: 5 });
  const phone = forkReplica(base, "phone");
  const tablet = forkReplica(base, "tablet");

  sell(phone, ISBN, 2);
  sell(tablet, ISBN, 1);
  assert.equal(value(phone, ISBN), 3);
  assert.equal(value(tablet, ISBN), 4);

  const phoneFirst = mergeReplicas(phone, tablet);
  const tabletFirst = mergeReplicas(tablet, phone);
  assert.equal(value(phoneFirst, ISBN), 2);
  assert.equal(value(tabletFirst, ISBN), 2);
  assert.deepEqual(phoneFirst.inventory, tabletFirst.inventory);

  const duplicate = mergeReplicas(phoneFirst, tablet);
  assert.deepEqual(duplicate.inventory, phoneFirst.inventory);
});

test("different ISBNs and three replicas merge independently", () => {
  const base = createInventory({ [ISBN]: 10, [ISBN2]: 2 });
  const phone = forkReplica(base, "phone");
  const tablet = forkReplica(base, "tablet");
  const warehouse = forkReplica(base, "warehouse");

  sell(phone, ISBN, 2);
  restock(tablet, ISBN2, 3);
  restock(warehouse, ISBN, 4);

  const leftGrouped = mergeReplicas(mergeReplicas(phone, tablet), warehouse);
  const rightGrouped = mergeReplicas(phone, mergeReplicas(tablet, warehouse));
  assert.deepEqual(leftGrouped.inventory, rightGrouped.inventory);
  assert.deepEqual(
    [value(leftGrouped, ISBN), value(leftGrouped, ISBN2)],
    [12, 5],
  );
});

test("state survives JSON transport", () => {
  const base = createInventory({ [ISBN]: 5 });
  const phone = forkReplica(base, "phone");
  restock(phone, ISBN, 2);

  const transported = JSON.parse(JSON.stringify(phone));
  assert.equal(value(transported, ISBN), 7);
  assert.deepEqual(mergeReplicas(phone, transported).inventory, phone.inventory);
});
```
